#!/usr/bin/env bash
set -Eeuo pipefail
test "$(id -u)" = 0 || { echo '请使用 sudo bash /tmp/folio-install.sh'; exit 1; }
if ! command -v node >/dev/null || ! command -v pm2 >/dev/null; then
  FOLIO_NVM_DIR="${NVM_DIR:-/root/.nvm}"
  if test -s "$FOLIO_NVM_DIR/nvm.sh"; then
    set +u
    . "$FOLIO_NVM_DIR/nvm.sh" --no-use
    set -u
    nvm use --silent default >/dev/null 2>&1 || nvm use --silent node >/dev/null 2>&1 || true
  fi
fi
for tool in node pm2 curl; do command -v "$tool" >/dev/null || { echo "缺少 $tool；请先载入已有 Node/PM2 环境。"; exit 1; }; done
stage=$(mktemp -d /tmp/lernicks-folio-XXXXXXXX)
trap 'rm -rf -- "$stage"' EXIT
cat > "$stage/patch.cjs" <<'FOLIO_PATCH'
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),vm=require('node:vm');
const entries=[['main','main/index.html'],['note','telegram-notes/public/index.html'],['tbl','tbl/index.html'],['mk','mk/index.html'],['document','mk/document.html']];
const block="<!-- FOLIO START -->\n<style id=\"folio-style\">\n/* Folio · 2026-10. Scoped to the four public tools and their existing new theme. */\n.folio-only{display:none!important}\nhtml.astra[data-folio] .folio-only{display:block!important}\nhtml.astra[data-folio]{--bg:#f7f6f2;--panel:#fffefa;--text:#252822;--muted:#6d7168;--line:#dedfd5;--article:#363a32;--a-paper:#fffefa;--a-soft:#eeeee6;--a-ink:#252822;--a-accent:#b34c2b;--a-on-accent:#fff;--f-accent:#b34c2b;--f-tint:#f4e8df;--f-serif:Georgia,\"Noto Serif SC\",\"Songti SC\",SimSun,serif;--red:#a63e36;--status:#397052;color-scheme:light}\nhtml.astra[data-folio=\"tbl\"]{--a-accent:#356c53;--f-accent:#356c53;--f-tint:#e8eee5}\nhtml.astra:is([data-folio=\"mk\"],[data-folio=\"document\"]){--a-accent:#70538c;--f-accent:#70538c;--f-tint:#eee8f1}\nhtml.astra[data-folio] body{background:var(--bg);color:var(--text);font-family:\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif;line-height:1.7}\nhtml.astra[data-folio] ::selection{background:var(--f-tint);color:var(--text)}\nhtml.astra[data-folio] :is(.page,.app){width:min(1180px,calc(100% - 80px));padding:28px 0 30px}\nhtml.astra[data-folio] :is(.topbar,.topnav){padding:0 0 24px;border-bottom:1px solid var(--line);gap:20px;flex-wrap:wrap}\nhtml.astra[data-folio] .brand{gap:12px}\nhtml.astra[data-folio] :is(.brand h1,.brand strong){font-size:18px;font-weight:650;letter-spacing:-.04em}\nhtml.astra[data-folio] :is(.mark,.logo){border-radius:50%;width:42px;height:42px;flex-basis:42px;background:var(--text);font:italic 24px var(--f-serif);color:var(--bg)}\nhtml.astra[data-folio] .logo{font:600 17px/1 \"Segoe UI\",sans-serif}\nhtml.astra[data-folio] :is(.brand p,.brand span){font:10px/1.5 Consolas,monospace;letter-spacing:.13em;color:var(--muted)}\nhtml.astra[data-folio] :is(.top-actions,.astra-header-actions){gap:12px}\nhtml.astra[data-folio] :is(.nav-btn,.home,.home-link){background:transparent;border:0;padding:8px 0;font-size:13px;color:var(--muted);text-decorati