hover{filter:brightness(.92)}\nhtml.astra[data-folio] :is(.btn.danger,.btn-danger){background:transparent;color:var(--red);border-color:#dfb9b3}\nhtml.astra[data-folio] :is(.field,.title-input,.admin-key-input,.copy-row input,.feedback-form input,.feedback-form textarea){color:var(--text);background:var(--a-paper);border-color:var(--line);border-radius:7px}\nhtml.astra[data-folio] :is(.meter,.progress){background:var(--a-soft)}\nhtml.astra[data-folio] :is(.meter i,.progress-bar){background:var(--f-accent)}\nhtml.astra[data-folio] :is(.info,.capacity){padding:24px}\nhtml.astra[data-folio] .side{gap:16px}\nhtml.astra[data-folio] .side,html.astra[data-folio] .side>*{min-width:0}\nhtml.astra[data-folio] :is(.tip,.rule)>div{min-width:0;overflow-wrap:anywhere}\nhtml.astra[data-folio] .side .capacity-head{flex-wrap:wrap;gap:8px}\nhtml.astra[data-folio] :is(.rule-icon,.tip i){color:var(--f-accent);background:var(--f-tint);border:0;border-radius:50%;box-shadow:none}\nhtml.astra[data-folio] :is(.info h3,.capacity-head strong,.history h3){font-size:15px;font-weight:600}\nhtml.astra[data-folio] .mode-badge{color:var(--f-accent);background:var(--f-tint);border:0;font-size:11px;padding:5px 9px;border-radius:5px}\nhtml.astra[data-folio] .key-warning{background:#f6efdb;border-color:#e4d9bb;color:#705e2c}\nhtml.astra[data-folio] footer{font-size:11px;padding-top:22px;margin-top:40px;color:var(--muted);letter-spacing:.025em}\n/* Main: an editorial opening, handmade paper specimens, and three equal entries. */\nhtml.astra[data-folio=\"main\"] .hero{padding:60px 0 50px;min-height:350px;display:grid;grid-template-columns:1.15fr 1fr;column-gap:36px;align-content:center}\nhtml.astra[data-folio=\"main\"] .hero>.eyebrow{grid-column:1;align-self:end}\nhtml.astra[data-folio=\"main\"] .hero h2{grid-column:1;font-size:clamp(40px,4.8vw,64px);font-weight:600;line-height:1.22;letter-spacing:-.065em;margin:20px 0;max-width:650px}\nhtml.astra[data-folio=\"main\"] .hero p{grid-column:1;max-width:470p