ius:50%;width:58px;height:58px;font-size:27px;background:var(--a-paper);color:var(--f-accent);margin:0 auto 18px;transform:none}\nhtml.astra[data-folio=\"tbl\"] .drop-zone h3{font-size:23px;font-weight:600;letter-spacing:-.04em}\nhtml.astra[data-folio=\"tbl\"] .drop-zone p{font-size:12px}\nhtml.astra[data-folio=\"tbl\"] .choose{display:inline-block;margin-top:8px;padding:10px 26px;font-size:13px}\nhtml.astra[data-folio=\"tbl\"] .admin-key-box{padding:20px 6px 6px;margin-top:6px}\nhtml.astra[data-folio=\"tbl\"] .history{padding:24px;margin-top:26px}\nhtml.astra[data-folio=\"tbl\"] .history-item{background:var(--f-tint);border-radius:8px}\nhtml.astra[data-folio=\"tbl\"] .result-preview{border-radius:7px}\n/* Compose and read: typography carries the design; mixed content stays intact. */\nhtml.astra[data-folio=\"mk\"] .editor-shell{grid-template-columns:minmax(0,1fr) 288px;gap:22px}\nhtml.astra[data-folio=\"mk\"] .editor{padding:26px}\nhtml.astra[data-folio=\"mk\"] .title-input{border:0;border-bottom:1px solid var(--line);border-radius:0;background:transparent;font-size:24px;font-weight:500;padding:10px 0 16px}\nhtml.astra[data-folio=\"mk\"] .field-label{font-size:11px;line-height:1.8}\nhtml.astra[data-folio=\"mk\"] .content-input{background:#faf9f6;border:1px solid var(--line);border-radius:8px;min-height:340px;font:14px/1.95 Consolas,\"Microsoft YaHei\",monospace;padding:22px;color:var(--text)}\nhtml.astra[data-folio=\"mk\"] .mode-row{margin:16px 0 22px}\nhtml.astra[data-folio=\"mk\"] .compose-preview{background:var(--a-paper);border-color:var(--line);border-radius:8px}\nhtml.astra[data-folio=\"mk\"] .editor-foot{padding-top:20px}\nhtml.astra[data-folio=\"mk\"] .create-button{font-size:13px;padding:12px 22px}\nhtml.astra[data-folio=\"document\"] .page,html.astra[data-folio=\"document\"] body.reader-mode .page{width:min(1060px,calc(100% - 64px))}\nhtml.astra[data-folio=\"document\"] .document-head{padding:46px 0 26px}\nhtml.astra[data-folio=\"document\"] .document-hea