c(100% - 36px);padding:20px 0 18px}\n html.astra[data-folio=\"note\"] .topnav nav{width:100%;justify-content:flex-start;gap:16px;flex-wrap:wrap}\n html.astra[data-folio=\"note\"] .topnav .folio-nav{width:auto;order:0;margin-left:auto}\n html.astra[data-folio=\"note\"] .topnav nav>.design-switch{margin-left:auto}\n html.astra[data-folio=\"note\"] .home-wrap{width:calc(100% - 40px);display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;padding:46px 0 60px;gap:0}\n html.astra[data-folio=\"note\"] .telegram-title{font-size:36px;line-height:1.35;margin:0 0 18px;align-self:stretch}\n html.astra[data-folio=\"note\"] .telegram-sub{font-size:13px;margin:0 0 35px}\n html.astra[data-folio=\"note\"] .telegram-card{width:calc(100% - 6px);max-width:none;min-height:0;transform:rotate(1deg);padding:30px 24px;align-self:center}\n html.astra[data-folio=\"note\"] .home-hint{margin-top:30px;font-size:11px;order:4}\n html.astra[data-folio=\"note\"] :is(.note-bar,.paper-page,.settings-panel){width:calc(100% - 36px)}\n html.astra[data-folio=\"note\"] .paper-page textarea{padding:28px 24px 48px}\n html.astra[data-folio=\"note\"] .note-actions{flex-wrap:wrap;gap:7px}\n html.astra[data-folio=\"note\"] .slug-input{font-size:15px}\n}\n@media(prefers-reduced-motion:reduce){html.astra[data-folio] *,html.astra[data-folio] *:before,html.astra[data-folio] *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}\n\n</style>\n<script id=\"folio-design\">\n/* Presentation only: never reads or writes note, document, account, or upload data. */\n(function(){\n 'use strict';\n var root=document.documentElement,site=root.getAttribute('data-astra-site');\n if(['main','note','tbl','mk','document'].indexOf(site)<0)return;\n root.setAttribute('data-folio',site);\n var links=[['note','便签','https://note.lernicks.cn'],['tbl','图床','https://tbl.lernicks.cn'],['mk','文档','https://mk.lernicks.cn']];\n var art='<svg viewBox=\"0 0 470 290\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\"><defs><pattern id=\"folio-dots\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\"><circle cx=\"1\" cy=\"1\" r=\".8\" fill=\"#c6c9ba\"/></pattern></defs><ellipse cx=\"240\" cy=\"152\" rx=\"202\" ry=\"123\" fill=\"url(#folio-dots)\"/><g transform=\"translate(259 51) rotate(9)\"><rect x=\"5\" y=\"7\" width=\"155\" height=\"184\" rx=\"3\" fill=\"#e5e0d8\"/><rect width=\"155\" height=\"184\" rx=\"3\" fill=\"#fffefa\" stroke=\"#d8d5cd\"/><path d=\"M20 37h115M20 111h115M20 130h92M20 149h105\" stroke=\"#d8d5cd\"/><text x=\"20\" y=\"26\" fill=\"#70538c\" font-size=\"9\" font-family=\"monospace\">03 / DOCUMENT</text><text x=\"77\" y=\"84\" text-anchor=\"middle\" fill=\"#70538c\" font-size=\"27\" font-family=\"Georgia\" font-style=\"italic\">E = mc²</text></g><g transform=\"translate(43 75) rotate(-10)\"><rect x=\"5\" y=\"7\" width=\"165\" height=\"156\" rx=\"3\" fill=\"#e5e0d8\"/><rect width=\"165\" height=\"156\" rx=\"3\" fill=\"#fffefa\" stroke=\"#d8d5cd\"/><text x=\"18\" y=\"27\" fill=\"#b34c2b\" font-size=\"9\" font-family=\"monospace\">01 / A LITTLE NOTE</text><path d=\"M18 40h129M18 88h129M18 106h115M18 124h126\" stroke=\"#d8d5cd\"/><text x=\"18\" y=\"70\" fill=\"#474b40\" font-size=\"14\" font-family=\"Microsoft YaHei\">把灵感留在这里。</text><circle cx=\"139\" cy=\"16\" r=\"10\" fill=\"#f0e4d7\"/><text x=\"135\" y=\"20\" font-size=\"12\" fill=\"#b34c2b\" font-family=\"Georgia\" font-style=\"italic\">L</text></g><g transform=\"translate(169 122) rotate(5)\"><rect x=\"5\" y=\"7\" width=\"154\" height=\"134\" rx=\"3\" fill=\"#d7d9cb\"/><rect width=\"154\" height=\"134\" rx=\"3\" fill=\"#fffefa\" stroke=\"#d8d5cd\"/><rect x=\"9\" y=\"9\" width=\"136\" height=\"99\" fill=\"#d1ddc9\"/><circle cx=\"113\" cy=\"33\" r=\"13\" fill=\"#f2dca6\"/><path d=\"M9 108V83l37-36 55 61\" fill=\"#91af86\"/><path d=\"M46 108l59-60 40 29v31\" fill=\"#4c7358\"/><text x=\"15\" y=\"123\" fill=\"#356c53\" font-size=\"8\" font-family=\"monospace\">02 / A MOMENT TO SHARE</text></g><path d=\"M97 33q20-13 37-2m-10-10 10 10-14 9M391 255q-15 18-37 14m10 10-10-10 13-8\" fill=\"none\" stroke=\"#a2a88f\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></svg>';\n function enhance(){\n  var header=document.querySelector(site==='note'?'.topnav':'.topbar');\n  if(header&&!header.querySelector('.folio-nav')){\n   var nav=document.createElement('nav');nav.className='folio-nav folio-only';nav.setAttribute('aria-label','Lernicks 工具');\n   links.forEach(function(item){var a=document.createElement('a');a.href=item[2];a.textContent=item[1];if(site===item[0]||(site==='document'&&item[0]==='mk'))a.setAttribute('aria-current','page');nav.appendChild(a)});\n   var actions=header.querySelector('.top-actions,.astra-header-actions');header.insertBefore(nav,actions||null);\n  }\n  if(site==='main'){\n   var hero=document.querySelector('.hero');\n   if(hero&&!hero.querySelector('.folio-hero-art')){var drawing=document.createElement('div');drawing.className='folio-hero-art folio-only';drawing.setAttribute('aria-hidden','true');drawing.innerHTML=art;hero.appendChild(drawing)}\n   var title=document.getElementById('astra-main-title');if(title&&!title.hasAttribute('data-folio-title')){title.innerHTML='小小工具，<br>装下你的灵感。';title.setAttribute('data-folio-title','')}\n   var sites=document.querySelector('.sites');if(sites&&!document.querySelector('.folio-section-label')){var label=document.createElement('div');label.className='folio-section-label folio-only';label.innerHTML='<strong>从这里，开始一件小事</strong><span>THE EVERYDAY COLLECTION / 01—03</span>';sites.before(label)}\n   [['note','便签电报','给一段话起个名字。随写随存，用链接分享，也可以设置访问密码。'],['image','公共图床','拖入或粘贴一张图片。获取直链，让眼前的画面出现在任何地方。'],['document','混合文档','把文字、公式和 HTML 写在同一页。认真排版，轻松分享。']].forEach(function(item){var card=document.querySelector('.card.'+item[0]);if(card&&!card.querySelector('.folio-copy')){var heading=card.querySelector('h3 .astra-only');if(heading)heading.textContent=item[1];var p=document.createElement('p');p.className='folio-copy folio-only';p.textContent=item[2];var old=card.querySelector('p');if(old)old.after(p)}});\n  }\n  if(site==='note'){\n   var noteTitle=document.querySelector('.telegram-title');if(noteTitle&&!noteTitle.hasAttribute('data-folio-title')){var original=noteTitle.textContent;noteTitle.innerHTML='';var old=document.createElement('span');old.className='legacy-only';old.textContent=original;noteTitle.appendChild(old);var fresh=document.createElement('span');fresh.className='folio-only';fresh.innerHTML='写点什么，<br>给需要的人。';noteTitle.appendChild(fresh);noteTitle.setAttribute('data-folio-title','')}\n   var brand=header&&header.querySelector('.brand');if(brand&&!brand.querySelector('.folio-note-brand')){var oldBrand=document.createElement('span');oldBrand.className='legacy-only';while(brand.firstChild)oldBrand.appendChild(brand.firstChild);brand.appendChild(oldBrand);var newBrand=document.createElement('span');newBrand.className='folio-note-brand folio-only';newBrand.innerHTML='<i aria-hidden=\"true\">L.</i><span>便签电报</span>';brand.appendChild(newBrand)}\n  }\n  var meta=document.querySelector('meta[name=\"theme-color\"]');if(meta&&root.classList.contains('astra'))meta.content='#f7f6f2';\n }\n document.addEventListener('DOMContentLoaded',function(){enhance();if(site==='note'){var app=document.getElementById('app');if(app)new MutationObserver(enhance).observe(app,{childList:true,subtree:true})}});\n window.addEventListener('lernicks-design-change',enhance);\n})();\n\n</script>\n<!-- FOLIO END -->\n";
const stage=process.argv[2],live=path.resolve(process.argv[3]||'/root');
if(!stage)throw Error('Missing staging directory');
function strip(s){return s.replace(/<!-- FOLIO START -->[\s\S]*?<!-- FOLIO END -->\s*/g,'')}
for(const[site,file]of entries){
 const target=path.join(live,file);assert.equal(fs.realpathSync(target),target,'Unexpected symlink: '+file);
 const before=fs.readFileSync(target,'utf8'),clean=strip(before);
 assert.ok(clean.includes('id="astra-theme"'),'Existing new design missing: '+file);
 assert.ok(clean.includes('data-astra-site="'+site+'"'),'Unexpected page: '+file);assert.ok(clean.includes('</head>'));
 const after=clean.replace('</head>',block+'</head>');assert.equal(strip(after),clean,'Existing page changed');
 for(const m of after.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/g))new vm.Script(m[1],{filename:file});
 const dest=path.join(stage,file);fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,after);console.log('Validated: '+file);
}
FOLIO_PATCH
specs=('main/index.html|1149|main-server' 'telegram-notes/public/index.html|3000|telegram-notes' 'tbl/index.html|1148|tbl-server' 'mk/index.html|1151|mk-server' 'mk/document.html|1151|mk-server')
for spec in "${specs[@]}"; do
 IFS='|' read -r file port process <<< "$spec"
 test -f "/root/$file" && test "$(readlink -f "/root/$file")" = "/root/$file"
 pm2 describe "$process" >/dev/null
done
node "$stage/patch.cjs" "$stage/pages"
backup=$(mktemp -d /root/folio-code-backup-XXXXXXXX)
chmod 700 "$backup"
for spec in "${specs[@]}"; do
 IFS='|' read -r file port process <<< "$spec"
 mkdir -p "$backup/$(dirname "$file")"
 cp -a "/root/$file" "$backup/$file"
done
processes=(main-server telegram-notes tbl-server mk-server)
rollback(){
 trap - ERR INT TERM
 echo "安装失败，恢复页面备份：$backup" >&2
 for spec in "${specs[@]}"; do
  IFS='|' read -r file port process <<< "$spec"
  cp -a "$backup/$file" "/root/$file" || true
 done
 for process in "${processes[@]}"; do pm2 restart "$process" >/dev/null || true; done
 exit 1
}
trap rollback ERR INT TERM
for spec in "${specs[@]}"; do
 IFS='|' read -r file port process <<< "$spec"
 temp="/root/$file.folio-$$"
 cp -a "/root/$file" "$temp"
 cat "$stage/pages/$file" > "$temp"
 mv -f "$temp" "/root/$file"
done
for process in "${processes[@]}"; do pm2 restart "$process" >/dev/null; done
for spec in "${specs[@]}"; do
 IFS='|' read -r file port process <<< "$spec"
 if [[ "$file" = 'mk/document.html' ]]; then
  cmp "$stage/pages/$file" "/root/$file"
  echo "OK: $file / installed reader template"
  continue
 fi
 endpoint=/
 curl -fsSL --retry 8 --retry-connrefused --retry-delay 2 --retry-max-time 30 --max-redirs 5 --max-time 30 "http://127.0.0.1:$port$endpoint" -o "$stage/check.html"
 grep -q 'id="folio-style"' "$stage/check.html"
 grep -q 'id="folio-design"' "$stage/check.html"
 echo "OK: $file / $port"
done
trap - ERR INT TERM
echo "FOLIO_DEPLOY_SUCCESS backup=$backup"
